import{z as l,x as i,o as r,c as d,q as n,j as B,D as A,d as E,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"团队知识库","description":"","frontmatter":{"title":"团队知识库","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc2-knowledge-base.md","filePath":"quant/rc2-knowledge-base.md","lastUpdated":1791413859000}'),p={name:"quant/rc2-knowledge-base.md"};function h(C,a,D,m,u,c){const t=i("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="团队知识库" tabindex="-1">团队知识库 <a class="header-anchor" href="#团队知识库" aria-label="Permalink to &quot;团队知识库&quot;">​</a></h1><div class="epigraph"><p>知识库不是案例的备份，是组织的二手记忆；它的第一条纪律不是「写」，是「标记失效」。</p><footer>—— 据站内研究复盘的负结果可检索口径与策略台账的知识管理分工整理</footer></div><p><a href="/quant/rc2-research-docs">上一课</a>把每项研究写成可冻结的一页案例。缺口在案例之上：案例各自成立，组织仍然失忆——同一个供应商字段怪癖、同一处时区陷阱、同一类失败模式，散在几百页案例里，检索不到就等于没写。本课写团队知识库：跨研究的第二层记忆装什么、怎么进、怎么防腐。它与<a href="/quant/sl-knowledge-management">策略台账</a>分工：那边管策略资产的生命周期记录，这边管研究过程的知识沉淀。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组织失忆的成本不是重复劳动，是重复<strong>风险</strong>。同一个数据坑，A 组三个月前绕过去了，B 组今天原样踩上——因为 A 组的知识活在他脑子里，离职或调组即清零。新人头三个月能提问的对象只有一个：老员工，而老员工的时间是团队最贵的资源。放任自流的解法通常是「建个 wiki」，然后得到一个只进不出的坟场：几百页没人敢删的页面，检索靠记忆文件名，内容真假与时效全凭运气。<strong>过期的知识比没有知识更危险</strong>：一条「该字段有误」若早已修复而仍躺在清单里，新人会绕开一个其实可用的字段，并且没人知道为什么绕。缺口因此是三样东西的合取：装什么、怎么进、怎么防腐。</p><p><span class="marginnote">直觉类比：过期的坑清单像过期的地铁施工公告——按它绕路的人白多走两站，还感激地以为公告帮了自己。坑记录与公告的区别在于：公告贴出去就没人管，知识库的每条记录带着「最后验证日期」，到期自动标灰，逼着每个引用者顺手当一次校对员。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="三类内容与入库标准" tabindex="-1">三类内容与入库标准 <a class="header-anchor" href="#三类内容与入库标准" aria-label="Permalink to &quot;三类内容与入库标准&quot;">​</a></h3><p>知识库装三类跨研究的知识。<strong>数据坑清单</strong>：供应商字段怪癖、公司行动修正行为、时区与对齐陷阱——<a href="/quant/de-data-versioning">数据版本化</a>与数据质量监控的副产品，按供应商与数据集归档。<strong>口径表</strong>：每个指标、每条清洗规则的唯一定义处，口径之争在此裁决，别处引用不定义。<strong>失败模式与家族分类</strong>：按<a href="/quant/alphaschema-ontology">因子本体</a>的骨架归档案例，让「又一个动量族衰减」能被检索。入库三条标准：有证据引用（实验 ID 或快照）、有日期、有署名——没有证据的段子不收；这与<a href="/quant/research-postmortem">研究复盘</a>「负结果可检索」是同一条款的组织级版本。</p>',9)),(r(),B(s,null,{default:A(()=>[o(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%A1%88%E4%BE%8B%20%E5%9D%91%20%E5%8F%A3%E5%BE%84%20%E5%B8%A6%E8%AF%81%E6%8D%AE%E4%B8%8E%E7%BD%B2%E5%90%8D%22%5D%20--%3E%20IN%7B%22%E5%85%A5%E5%BA%93%E4%B8%89%E6%A0%87%E5%87%86%22%7D%0A%20%20IN%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20KB%5B%22%E7%9F%A5%E8%AF%86%E5%BA%93%EF%BC%9A%E6%A3%80%E7%B4%A2%20%2B%20%E6%A0%87%E7%AD%BE%22%5D%0A%20%20IN%20--%3E%7C%E7%BC%BA%E8%AF%81%E6%8D%AE%7C%20BACK%5B%22%E9%80%80%E5%9B%9E%EF%BC%9A%E8%A1%A5%E8%AF%81%E6%8D%AE%E5%86%8D%E8%BF%9B%22%5D%0A%20%20KB%20--%3E%20STALE%7B%22%E5%A4%8D%E5%AE%A1%EF%BC%9A%E5%88%B0%E6%9C%9F%E6%9C%AA%E9%AA%8C%E8%AF%81%22%7D%0A%20%20STALE%20--%3E%7C%E8%BF%87%E6%9C%9F%7C%20GRAY%5B%22%E6%A0%87%E7%81%B0%EF%BC%9A%E4%B8%8D%E5%88%A0%E9%99%A4%22%5D%0A%20%20STALE%20--%3E%7C%E5%A4%8D%E9%AA%8C%7C%20KB%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("防腐的机制是"),e("strong",null,"失效标记加复审责任"),E("，不是删除。每条知识带「最后验证日期」，复审到期未验证自动标灰：标灰的内容仍可检索，但带显著警告——历史也是证据，「当时错在哪」本身有检索价值，删掉就把教训一起删了。复审责任落在使用者身上：谁引用、谁顺手复验并刷新日期，比设专职管理员可持续。检索优先于目录：全文检索加标签是主路径，目录只留三层——目录编得再细，也细不过组织分裂的速度。")],-1)),a[5]||(a[5]=e("p",null,"为什么这套机制成立：它把知识从「人的记忆」搬到「带时间戳的记录」，并且让记录自己报告自己的年龄。新人的问题从「问问老王」变成「查坑清单」；查不到的东西才升级为提问，而每次升级提问再沉淀入库，知识库就完成一次生长。反过来，没有日期与复审的库，每次检索都要先猜真假——猜的成本高过问人，库就被弃用，回到人治。",-1)),(r(),B(s,null,{default:A(()=>[o(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%96%B0%E4%BA%BA%E9%81%87%E5%88%B0%E9%97%AE%E9%A2%98%22%5D%20--%3E%20S%7B%22%E5%85%88%E6%9F%A5%E5%9D%91%E6%B8%85%E5%8D%95%22%7D%0A%20%20S%20--%3E%7C%22%E6%9F%A5%E5%88%B0%E4%B8%94%E5%9C%A8%E6%9C%89%E6%95%88%E6%9C%9F%22%7C%20U%5B%22%E7%9B%B4%E6%8E%A5%E9%87%87%E7%94%A8%20%E5%B9%B6%E5%88%B7%E6%96%B0%E9%AA%8C%E8%AF%81%E6%97%A5%E6%9C%9F%22%5D%0A%20%20S%20--%3E%7C%22%E6%9F%A5%E5%88%B0%E4%BD%86%E5%B7%B2%E6%A0%87%E7%81%B0%22%7C%20V%7B%22%E5%A4%8D%E9%AA%8C%EF%BC%9A%E4%BB%8D%E6%88%90%E7%AB%8B%EF%BC%9F%22%7D%0A%20%20V%20--%3E%7C%22%E6%88%90%E7%AB%8B%22%7C%20U%0A%20%20V%20--%3E%7C%22%E4%B8%8D%E6%88%90%E7%AB%8B%22%7C%20UPD%5B%22%E6%9B%B4%E6%96%B0%E6%9D%A1%E7%9B%AE%20%E8%AE%B0%E5%BD%95%E6%96%B0%E8%AF%81%E6%8D%AE%22%5D%0A%20%20S%20--%3E%7C%22%E6%9F%A5%E4%B8%8D%E5%88%B0%22%7C%20ASK%5B%22%E5%8D%87%E7%BA%A7%E6%8F%90%E9%97%AE%EF%BC%9A%E9%97%AE%E4%BA%BA%22%5D%0A%20%20ASK%20--%3E%20RES%5B%22%E9%97%AE%E9%A2%98%E8%A7%A3%E5%86%B3%22%5D%0A%20%20RES%20--%3E%20NEW%5B%22%E6%B2%89%E6%B7%80%E6%96%B0%E6%9D%A1%E7%9B%AE%E5%85%A5%E5%BA%93%20%E5%BA%93%E5%AE%8C%E6%88%90%E4%B8%80%E6%AC%A1%E7%94%9F%E9%95%BF%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">术语翻译：「标灰」就是给知识贴一张「可能已过期」的告示，而不撕掉旧告示——「这个供应商当年这么坑过」本身就是证据，新人复查时知道坑的来龙去脉；直接删除等于烧掉案卷，同一个坑换件马甲就能再骗一次组织。</span></p><p><span class="marginnote">一个可操作的启动口径：知识库不从「整理历史」起步，从「拦下一次事故」起步——每次跨团队事故与返工，先落一条带判据的坑记录，历史知识在头三个月里自然长出骨架，比一次性大迁徙快得多。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>知识库不承载结论级研究记录——那是<a href="/quant/rc2-research-docs">研究文档</a>与案例库的事；库里的条目指向案例，不复述案例。它也不裁决口径：口径表记录裁决结果，裁决流程属于委员会（下一课）。别把知识库当协作沟通工具：讨论与争论留在评审与会议里，库只收沉淀物；把待办、草稿、情绪倾倒进库，检索信噪比立刻崩坏。最后，库存有组织偏差：署名与判据让幸存者偏差比散装八卦好一点，但不消除——流传下来的永远是有人记得写下的，这层偏差只能靠复盘归档的强制条款兜底。</p><p><span class="marginnote">常见误区：初学者容易以为「建个 wiki」就是知识管理。只进不出的库比没有更糟：条目越堆越多、真假不辨，检索信噪比崩坏后没人再查，组织悄悄回到「问老王」的人治。知识管理的第一性约束不是「多存」，是「查到的每条都可信」——防腐机制先于收集热情。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>组织失忆的代价是重复风险；过期的知识比没有知识更危险，防腐优先于收集。</li><li>三类内容：数据坑清单、口径表（唯一定义处）、失败模式与家族分类（挂本体骨架）。</li><li>入库三标准：证据引用、日期、署名；没有证据的段子不收。</li><li>防腐机制：最后验证日期加到期标灰，标灰不删除；谁引用谁复验。</li><li>出处：站内<a href="/quant/research-postmortem">研究复盘</a>的归档口径、<a href="/quant/sl-knowledge-management">策略台账</a>的知识管理分工、<a href="/quant/alphaschema-ontology">因子本体</a>与<a href="/quant/de-data-versioning">数据版本化</a>各课。</li></ul>',7))])}const F=l(p,[["render",h]]);export{g as __pageData,F as default};
